"""Portable synthetic model fixtures generated by retained Python development utilities."""
import datetime as dt
import json
import sys
from pathlib import Path

ROOT=Path(__file__).resolve().parents[2]
sys.path.insert(0,str(ROOT/"backend"))
import pandas as pd
from cfo.forecast import model as fm

out=Path(__file__).resolve().parent/"fixtures"
rows=[]
start=dt.date(2025,1,1)
for i in range(120):
    day=start+dt.timedelta(days=i)
    if not (50<=i<58):
        rows.extend([{"booking_date":str(day),"amount":100+i/10+(day.weekday()%3)*11,"category":"revenue"},{"booking_date":str(day),"amount":-(15+i/100),"category":"food"}])
    if day.day==1:rows.append({"booking_date":str(day),"amount":-1000.,"category":"rent"})
    if day.day==28:rows.append({"booking_date":str(day),"amount":-2000.,"category":"payroll"})
    if day.day==10:rows.append({"booking_date":str(day),"amount":-[880.,1105.,2030.][day.month%3],"category":"tax"})
    if day.day==15:rows.append({"booking_date":str(day),"amount":-250.,"category":"partner_investment"})
frame=pd.DataFrame(rows)
frame["booking_date"]=pd.to_datetime(frame["booking_date"])
frame["amount"]=frame["amount"].astype(float)
for feature_set in ["calendar","level","level_baseline","components"]:
    model=fm.train(frame,feature_set=feature_set,params={"n_estimators":8,"max_depth":2,"learning_rate":0.1},holdout_days=0,band=False,log_to_mlflow=False)
    if feature_set=="components":model.band_spec={"p":0.7,"lower":1.1,"upper":2.2,"horizon_measured":90}
    model.save(out/f"{feature_set}.json")
(out/"transactions.json").write_text(json.dumps(rows,indent=2)+"\n")
print("Generated four portable synthetic models and history")
